from HiggsAnalysis.CombinedLimit.PhysicsModel import * 

### base python class to study the Higgs coupling structure in the SMEFT Higgs basis 
   
class HWWSMEFTciHB(PhysicsModel):
    def __init__(self):

        self.info = 1

    def setModelBuilder(self, modelBuilder):

        PhysicsModel.setModelBuilder(self,modelBuilder)
        self.modelBuilder.doModelBOnly = False

    def getYieldScale(self,bin,proc):
        scaling=1.

        # SM treatment (CR or minor signal)  
        if   "VBF_T1"  in proc : scaling = "scale_ewk_T1"
        elif "ggZH_T1" in proc : scaling = "scale_ggf_T1"
        elif "ZH_T1"   in proc : scaling = "scale_ewk_T1"
        elif "WH_T1"   in proc : scaling = "scale_ewk_T1"
        elif "ggF_T1"  in proc : scaling = "scale_ggf_T1"

        # EFT treatment 
        if   "VBF_H" in proc : scaling = "scale_8C2V_"+proc[4:]
        elif "ZH_H"  in proc : scaling = "scale_8C2V_"+proc[3:]
        elif "WH_H"  in proc : scaling = "scale_4C2V_"+proc[3:]
        elif "ggF_H" in proc : scaling = "scale_4C1V_"+proc[4:]

        if self.info == 1 :print("Will scale", proc, "in bin", bin, "by", scaling)

        return scaling

    def setPhysicsOptions(self,physOptions):

        print("no input params")

    def doParametersOfInterest(self): 

        # EFT Higgs basis HVV couplings 

        self.modelBuilder.doVar('cZ[0, -1, 1]')
        self.modelBuilder.doVar('cZZ[0, -2, 2]')
        self.modelBuilder.doVar('cZZt[0, -2, 2]')
        self.modelBuilder.doVar('cZB[0, -0.5, 0.5]')
        self.modelBuilder.doVar('cZg[0, -3, 3]')
        self.modelBuilder.doVar('cZgt[0, -3, 3]')
        self.modelBuilder.doVar('cgg[0, -10, 10]')
        self.modelBuilder.doVar('cggt[0, -10, 10]')

        poi='cZ,cZZ,cZZt,cZB,cZg,cZgt,cgg,cggt'

        # HVV Amplitude couplings from EFT couplings 

        self.modelBuilder.doVar('expr::pi("3.1416", )')
        self.modelBuilder.doVar('expr::cw("0.8768", )')
        self.modelBuilder.doVar('expr::sw("0.4808", )')
        self.modelBuilder.doVar('expr::e2("0.0917", )')
        self.modelBuilder.doVar('expr::mZ("91.2", )')
        self.modelBuilder.doVar('expr::L("100", )')
        self.modelBuilder.doVar('expr::mZ2("@0*@0", mZ)')
        self.modelBuilder.doVar('expr::L2("@0*@0", L)')
        self.modelBuilder.doVar('expr::csw("@0*@0-@1*@1", cw, sw)')
        self.modelBuilder.doVar('expr::alpha("@0/4*@1", e2, pi)')

        self.modelBuilder.doVar('expr::a1("@0 + 1", cZ)')
        self.modelBuilder.doVar('expr::a2("-1*@0*(@1/(2*@2*@2*@3*@3))", cZZ, e2, sw, cw)')
        self.modelBuilder.doVar('expr::a3("-1*@0*(@1/(2*@2*@2*@3*@3))", cZZt, e2, sw, cw)')
        self.modelBuilder.doVar('expr::k1("@0*(@1/(@2*@2*@3))*@4", cZB, e2, sw, mZ2, L2)')
        self.modelBuilder.doVar('expr::z2("-1*@0*(@1/(2*@2*@3))", cZg, e2, sw, cw)')
        self.modelBuilder.doVar('expr::z3("-1*@0*(@1/(2*@2*@3))", cZgt, e2, sw, cw)')
        self.modelBuilder.doVar('expr::g2("-1*@0*(@1/2)", cgg, e2)')
        self.modelBuilder.doVar('expr::g3("-1*@0*(@1/2)", cggt, e2)')

        # SU2xU1 relationship 

        self.modelBuilder.doVar('expr::a1WW("@0", a1)')
        self.modelBuilder.doVar('expr::a2WW("@0*@0*@2 + @1*@1*@3 + 2*@1*@0*@4", cw, sw, a2, g2, z2)')
        self.modelBuilder.doVar('expr::a3WW("@0*@0*@2 + @1*@1*@3 + 2*@1*@0*@4", cw, sw, a3, g3, z3)')
        self.modelBuilder.doVar('expr::k1WW("@5/@0 + 2*@2*@2*@3*(@7-@6)/(@4*@0) + 2*@3*(@2/@1)*(@8/@4)", csw, cw, sw, L2, mZ2, k1, a2, g2, z2)')
        self.modelBuilder.doVar('expr::k2("2*@2*@1*@5/@0 + 2*@2*@1*@3*(@7-@6)/(@4*@0) + 2*@3*(@8/@4)", csw, cw, sw, L2, mZ2, k1, a2, g2, z2)')

        # Width equations 

        self.modelBuilder.doVar('expr::kappa("1.0", )')
        self.modelBuilder.doVar('expr::kappa_tilde("0.0", )')
        self.modelBuilder.doVar('expr::R_ZZ("4*(@0*@0/4. + 0.17*@1*@1 + 0.09*@3*@3 + 0.04*@4*@4 + 0.10*@2*@2 + 79.95*@5*@5 + 75.23*@6*@6 +29*@7*@7 + 29.47*@8*@8 + 0.81*@0*@1/2 + 0.5046*@0*@3/2 - 0.1901*@0*@2/2 - 1.56*@0*@5/2 + .06*@0*@7/2  + 0.21*@3*@1 - 0.07*@1*@2 -0.64*@1*@5 - 0.05*@3*@2 - 0.51*@3*@5 - 0.02*@3*@7 + 0.36*@4*@6 -0.57*@4*@8 + 1.8*@2*@5 - 0.05*@2*@7 -1.84*@5*@7 - 2.09*@6*@8)", a1, k1, k2, a2, a3, z2, z3, g2, g3)')
        self.modelBuilder.doVar('expr::R_WW("4*(@0*@0/4. + 0.1320*@1*@1 + 0.1944*@2*@2 + 0.08075*@3*@3 + 0.7204*@0*@1/2. + 0.7437*@0*@2/2. + 0.2774*@1*@2)", a1WW, k1WW, a2WW, a3WW)')
        self.modelBuilder.doVar('expr::kQz("-(6*@0/@1)*@2", pi, alpha, z2)')
        self.modelBuilder.doVar('expr::kQz_tilde("-(4*@0/@1)*@2", pi, alpha, z3)')
        self.modelBuilder.doVar('expr::R_Zgm("4*(1.11965*@0*@0/4 - 0.12652*@0*@2/2 + 0.00348*@0*@2/2 -0.13021*@0*@4/2 + 0.00357*@2*@2  + 0.000003*@2*@2 - 0.00018*@2*@2 + 0.00377*@4*@4 + 0.00734*@2*@4 - 0.00019*@2*@4 +0.00849*@1*@1 + 0.000004*@1*@1 - 0.00025*@1*@1 + 0.00883*@3*@3 + 0.01723*@1*@3 - 0.00024*@1*@3)", a1WW, kappa_tilde, kappa, kQz_tilde, kQz)')
        self.modelBuilder.doVar('expr::kQg("-(3*@0/@1)*@2", pi, alpha, g2)')
        self.modelBuilder.doVar('expr::kQg_tilde("-(2*@0/@1)*@2", pi, alpha, g3)')
        self.modelBuilder.doVar('expr::R_gmgm("4*(1.60932*@0*@0/4 - 0.69064*@0*@2/2 + 0.00912*@0*@2/2 - 0.49725*@0*@4/2 + 0.07404*@2*@2 + 0.00002*@2*@2 - 0.00186*@2*@2 + 0.03841*@4*@4 + 0.10666*@2*@4 - 0.00136*@2*@4  + 0.20533*@1*@1 + 0.00006*@1*@1 - 0.003*@1*@1 + 0.10252*@3*@3 + 0.29018*@1*@3 - 0.00202*@1*@3)", a1WW, kappa_tilde, kappa, kQg_tilde, kQg)')
        self.modelBuilder.doVar('expr::R_gg("1.1068*@1*@1 + 0.0082*@1*@1 - 0.1150*@1*@1 + 2.5717*@0*@0 + 0.0091*@0*@0 - 0.1982*@0*@0", kappa_tilde, kappa)')
        self.modelBuilder.doVar('expr::R_kk("@1*@1 + @0*@0", kappa_tilde, kappa)')
        self.modelBuilder.doVar('expr::gammaH("1/((0.5824*@0 + 0.2137*@1 + 0.08187*@2 + 0.06272*@0 + 0.02891*@0 + 0.02619*@3 + 0.002270*@4 +  0.001533*@5 + 0.0002176*@0)/0.9998)", R_kk, R_WW, R_gg, R_ZZ, R_gmgm, R_Zgm)')

        # Final scaling terms for SM T1 signals 

        self.modelBuilder.factory_("expr::scale_ewk_T1(\"pow(@0,4)*@1\",a1, gammaH)")
        self.modelBuilder.factory_("expr::scale_ggf_T1(\"pow(@0,2)*@1\",a1, gammaH)")

        # Final scaling terms for 8C2V signal Hypotheses 

        #119 terms so split in 4 (A-D)
        self.modelBuilder.factory_("expr::EH1A(\"(pow(@0,4) + pow(@0,3)*@1*-7.0 + pow(@0,3)*@2*-7.0 + pow(@0,3)*@3*7.0 + pow(@0,3)*@4*-7.0 + pow(@0,3)*@5*-7.0 + pow(@0,3)*@6*-7.0 + pow(@0,3)*@7*-7.0 + pow(@0,2)*@1*@2*5.0 + pow(@0,2)*@1*@3*-5.0 + pow(@0,2)*@1*@4*5.0 + pow(@0,2)*@1*@5*5.0 + pow(@0,2)*@1*@6*5.0 + pow(@0,2)*@1*@7*5.0 + pow(@0,2)*@2*@3*-5.0 + pow(@0,2)*@2*@4*5.0 + pow(@0,2)*@2*@5*5.0 + pow(@0,2)*@2*@6*5.0 + pow(@0,2)*@2*@7*5.0 + pow(@0,2)*@3*@4*-5.0 + pow(@0,2)*@3*@5*-5.0 + pow(@0,2)*@3*@6*-5.0 + pow(@0,2)*@3*@7*-5.0 + pow(@0,2)*@4*@5*5.0 + pow(@0,2)*@4*@6*5.0 + pow(@0,2)*@4*@7*5.0 + pow(@0,2)*@5*@6*5.0 + pow(@0,2)*@5*@7*5.0 + pow(@0,2)*@6*@7*5.0 + @0*@1*@2*@3 )*@8\", a1, a2, a3, k1, z2, z3, g2, g3, gammaH)")
